Hello,
according to

[testthat 3rd edition](https://testthat.r-lib.org/articles/third-edition.html)

`testthat::with_mock` will be deprecated. While I'm looking forward to this edition, I have difficulties in replacing `testthat::with_mock`.
I could not find a way to mock external functions in R6 methods which are called via expressions. `mockery` claims that one can mock external functions in R6 methods, but this seems to me to work only if the external functions are called directly.
As you can see in the example below, this works with `testthat::with_mock`.

```
external_function <- function() {
  message("this is the external_function")
}

A <- R6::R6Class(
  classname = "A",
  public = list(
    initialize = function() {
      message("initialize")
    }

    , run1 = function() {
      message(external_function())
    }

    , run2 = function(expr) {
      eval(expr)
    }

    , run3 = function(expr) {
      withCallingHandlers(
        expr = expr,
        error = function(e) {
          message(e$message)
        },
        warning = function(w) {
          message(w)
        }
      )
    }

  )
)

obj <- A$new()
obj$run1() #this is the external_function

m <- mockery::mock("this is the mock")
obj <- A$new()
mockery::stub(
  where = obj$run1,
  what = "external_function",
  how = m
)
obj$run1() #this is the mock

#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
obj$run2(print(external_function())) #this is the external function

mockery::stub(
  where = obj$run2,
  what = "external_function",
  how = m
)
obj$run2(print(external_function())) #this is the external function <<-- NOT MOCKED
