compare.POSIXt <- function(x, y, ..., check.attributes = TRUE) {
  x <- as.POSIXct(x)
  y <- as.POSIXct(y)

  if (!check.attributes || attr(x,'tzone') == attr(y,'tzone')) {
    equal <- all.equal(x, y, check.attributes = check.attributes, ...)
    if (isTRUE(equal)) return(testthat:::comparison(TRUE,"Equal"))
  }

